//  Rez an object, and drop this script in it.
//  This will launch it at the owner.
default
{
state_entry
()
{
key
ownerKey
=
llGetOwner
();
vector
ownerPosition
=
llList2Vector
(
llGetObjectDetails
(
ownerKey
,
[
OBJECT_POS
]),
0
);
//  if the owner is not in the sim, stop fooling around
if
(
llGetAgentSize
(
ownerKey
)
==
ZERO_VECTOR
)
return
;
//  else
llSetStatus
(
STATUS_PHYSICS
,
TRUE
);
vector
objectPosition
=
llGetPos
();
vector
direction
=
llVecNorm
(
ownerPosition
-
objectPosition
);
llApplyImpulse
(
direction
*
llGetMass
(),
0
);
}
}

